# Chronos Academy - instala: secao "Aulas mais recentes" que encolhe/expande (sem mostrar "ha quanto tempo") + tudo dos passos anteriores
# Rode este script na raiz do projeto (pasta chronos-academy), no PowerShell.
$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json")) {
    Write-Host "ERRO: rode este script dentro da pasta do projeto (chronos-academy)." -ForegroundColor Red
    exit 1
}

Write-Host "1) Fazendo backup rapido (commit vazio) antes de comecar..." -ForegroundColor Cyan
git add -A
git commit -m "Backup antes de instalar: Aulas mais recentes encolhe/expande" --allow-empty -q
if ($LASTEXITCODE -ne 0) { Write-Host "ERRO no backup. Nada foi alterado." -ForegroundColor Red; exit 1 }

Write-Host "2) Aplicando as atualizacoes (etapas ja feitas antes sao puladas sozinhas)..." -ForegroundColor Cyan

